ee:variables.ee:set-variable:
%dw 2.0
output application/json

var fechaActual = (now() >> "UTC-5") as String {format: "dd/MM/yyyy HH:mm:ss"}

var fechaMongo = {
        "\$date": (now() >> "UTC-5") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
    }
---
{
	actual: fechaActual,
	mongo: fechaMongo
}

%dw 2.0
output application/json

// pluck extrae los valores del objeto payload ("0","1","2" -> sus payloads), sin importar cuántas rutas tenga el scatter-gather
var resultadosRutas = payload pluck ((value, key) -> value.payload)

var todasLasValidaciones = resultadosRutas flatMap (regla) -> regla.detailEvaluated
var reglasInvalidas = todasLasValidaciones filter (v) -> v.isValid == false
---
{
	isValid: sizeOf(reglasInvalidas) == 0,
	reglas: resultadosRutas,
	camposInvalidos: reglasInvalidas
}

ee:message.ee:set-payload:
%dw 2.0 output application/json
import modules::GlobalFunctions as global
var idCatalogo = vars.objectServicioActivo.Bundles[0].id_catalogo var bundlesConstantesNull = ["opcionales", "caracteristicas_bundle", "estados_bundle", "bundle_auxiliar"]
var precioReposicion = ((vars.responseOfertaProducto.precio_oferta default []) filter ((p) -> upper(trim(p.canal_venta default "")) == "DISTRIBUIDOR"))[0].precio_con_iva
fun crearFase(fase, estado, resultado = null, causal = null) = { Fase: fase, Fecha_Ejecucion: global::fechaMongo(), Resultado: resultado, Causal_Fase: causal, Usuario_Creo: "PortalLTE", Estado: estado, Detalle_Fase: [ { Fecha_Registro: global::fechaMongo(), Codigo: null, Detalle: null } ], Reintentos: 0, actualizacion_extractor: "1" }
--- { "query" : { "insert": p('mongo-db-sapi.collections.orden-movil'), "documents": [ { Tipo_Documento: vars.requestOrder.customer.documentType, Numero_Identificacion: vars.requestOrder.customer.documentNumber, CUN: vars.cunNumber.cun, Id_Distribuidor: 0, Tipo_Orden: "Tramite LTE", Subtipo_Orden: "Reposicion Sim", Estado_Orden: "PENDIENTE", Causal_Estado_Orden: null, Numero_Orden: vars.orderNumber, Fecha_Creacion_Orden: global::fechaMongo(), Usuario_Creador: "PortalLTE", Usuario_Modificador: "PortalLTE", Usuario_Vendedor: "PortalLTE", Fecha_Actualizacion_Orden: global::fechaMongo(), Canal: vars.requestOrder.channel, Subcanal: "PORTAL LTE", Causal_Retiro_Cliente: null, Forma_Entrega_Contrato: null, Fecha_Inicio_Contrato: null, Id_Orden_Sistema_Origen: vars.orderNumber, Sistema_Origen: "MDM-MOV", IMEI: "", num_agrupacion: if (idCatalogo != null) idCatalogo as Number else null, tipo_entrega_factura: null, tipo_plan: vars.objectServicioActivo.Tipo_Linea, Flag_Envio_Recibo: false, codigo_operador: null, celular_portabilidad: null, tipo_plan_donante: null, Caracteristicas_Orden: [ { Caracteristica: "integration_id", Valor: vars.objectServicioActivo.Integration_Id, Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "Tipo Reno / Repo", Valor: "Reposicion SIM", Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "MSISDN", Valor: vars.requestOrder.through.connectionNumber, Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "PERFIL", Valor: "CALL", Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "iccid_anterior", Valor: vars.objectServicioActivo.ICCID, Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "PART_NUMBER", Valor: "110-00007", Accion: "", actualizacion_extractor: "1" }, { Caracteristica: "OL_Depto_CodDANE", Valor: vars.requestOrder.through.delivery.geographicAddress.stateOrProvinceCode, Accion: "OL_Depto_CodDANE", actualizacion_extractor: "1" }, { Caracteristica: "OL_Depto", Valor: vars.responseDepartment."_id"."\$oid", Accion: "OL_Depto", actualizacion_extractor: "1" }, { Caracteristica: "OL_Ciudad_CodDANE", Valor: vars.requestOrder.through.delivery.geographicAddress.cityCode, Accion: "OL_Ciudad_CodDANE", actualizacion_extractor: "1" }, { Caracteristica: "OL_Direccion", Valor: vars.requestOrder.through.delivery.geographicAddress.formattedAddress, Accion: "OL_Direccion", actualizacion_extractor: "1" }, { Caracteristica: "OL_Barrio", Valor: vars.requestOrder.through.delivery.geographicAddress.locality, Accion: "OL_Barrio", actualizacion_extractor: "1" }, { Caracteristica: "OL_Email", Valor: vars.requestOrder.through.delivery.geographicAddress.contactEmail, Accion: "OL_Email", actualizacion_extractor: "1" }, { Caracteristica: "TIPO_ENTREGA", Valor: vars.requestOrder.through.delivery."type", Accion: "TIPO_ENTREGA", actualizacion_extractor: "1" } ], Pago: [ { Tipo_Recaudo: "Equipo", Forma_Pago: null, Recibo_Pago: "", Valor_Pagado: (precioReposicion default "0") as String, Valor_Facturado: (precioReposicion default "0") as String, Valor_Sin_Iva: "0", Fecha_Pago: global::fechaMongo(), Banco: vars.requestOrder.through.payment.bankCode, Canal_Pago: vars.requestOrder.through.payment.paymentChannel, Fecha_Limite_Pago: null, Numero_Confirmacion: "", Estado: null, Codigo_Respuesta: null, Mensaje_Respuesta: null, pago_online: null, actualizacion_extractor: "1" } ], Validacion: null, Fase_Orden: [ crearFase("ORDEN CREADA", "CLIENTE CARGADO"), crearFase("FACTURA", "EXITOSO"), crearFase("PAGO", "EXITOSO"), crearFase("COBRO SIM", "EXITOSO"), crearFase("DESPACHO OL", "EXITOSO", "", "OK") ], Cuenta_Facturacion: vars.objectServicioActivo.Cuenta_Facturacion, Cuenta_Facturacion_Equipo: null, Pago_Anticipado: if (upper(trim(vars.objectServicioActivo.Tipo_Linea default "")) == "POSPAGO") "SI" else null, Valor_Recaudo: "0", Reportado_Pago: null, Bundle_activo: (vars.objectServicioActivo.Bundles default []) map ((bundle) -> (bundle -- bundlesConstantesNull) ++ { opcionales: null, caracteristicas_bundle: null, estados_bundle: null, bundle_auxiliar: null } ), Bundle_orden: vars.objectServicioActivo.Bundles, Direccion: null, actualizacion_extractor: "1", Promociones: null, ciclo_facturacion: vars.responseCuentaFacturacion.objectCuentaFacturacion.Ciclo_Facturacion, iccid: null, producto_seleccionado: null } ] } }

%dw 2.0
output application/json
---
{
    code: if(vars.resultadoOrden.result.ok > 0) "200" else "500",
    messageResponse: if(vars.resultadoOrden.result.ok > 0) "Order Created" else "Error Created Order",
    order: {
        orderNumber: vars.orderNumber default "",
        cun: vars.cunNumber.cun,
        rulesApplied: vars.cumulativeRules.reglas
    }
}
